import { createElement } from "../dom.js";
export function RulesPage() {
    const page = createElement("section", "page-grid");
    const intro = createElement("div", "retro-window");
    intro.append(createElement("h1", "hero-title", "Rules"), createElement("span", "hero-subtitle", "ПРАВИЛА COURIER RUSH"), createElement("p", "hero-text", "Courier Rush — це гра про кур’єра, який розвозить посилки містом, дотримується правил дорожнього руху та намагається набрати якомога більше балів."));
    const rulesGrid = createElement("div", "rules-grid");
    const rules = [
        {
            title: "1. Обери режим гри",
            text: "Перед початком потрібно вибрати режим. У класичному режимі ти сам обираєш замовлення зі списку. В аркадному режимі замовлення видаються автоматично, а головна мета — набрати максимум балів за 90 секунд."
        },
        {
            title: "2. Мета гри",
            text: "Доставляй посилки клієнтам швидко й акуратно. Чим більше успішних доставок і чим менше порушень, тим кращий результат у рейтингу."
        },
        {
            title: "3. Класичний режим",
            text: "У класичному режимі вибери замовлення, забери посилку на парковці складу та достав її клієнту. Після завершення доставки можна вибрати наступне замовлення."
        },
        {
            title: "4. Аркадний режим",
            text: "В аркадному режимі гра сама видає наступне замовлення. Після кожної доставки одразу з’являється нова ціль. Час обмежений, тому важливо рухатися швидко, але без порушень."
        },
        {
            title: "5. Склад і клієнти",
            text: "Посилки забираються на службовій парковці складу. Клієнти позначені маркерами на карті. Щоб виконати замовлення, потрібно спочатку заїхати до складу, а потім до клієнта."
        },
        {
            title: "6. Бали",
            text: "За кожну доставку нараховуються бали. Більша винагорода, вищий пріоритет, швидка доставка та більша вага посилки можуть дати кращий результат."
        },
        {
            title: "7. Штрафи",
            text: "Бали знімаються за прострочені замовлення, зіткнення з транспортом, проїзд на червоне світло та перевищення швидкості біля радара."
        },
        {
            title: "8. Дорожній рух",
            text: "На дорогах їздять інші автомобілі. Їх потрібно об’їжджати та не створювати аварій. На світлофорах слід зупинятися на заборонений сигнал."
        },
        {
            title: "9. Пішоходи",
            text: "Пішоходи переходять дорогу по переходах. Якщо кур’єр збиває пішохода, гра одразу завершується."
        },
        {
            title: "10. Рейтинг",
            text: "Після завершення гри результат зберігається в рейтингу. Для класичного та аркадного режимів результати відображаються окремо."
        }
    ];
    rules.forEach((rule) => {
        const card = createElement("article", "retro-card rule-card");
        card.append(createElement("h2", "", rule.title), createElement("p", "", rule.text));
        rulesGrid.appendChild(card);
    });
    page.append(intro, rulesGrid);
    return page;
}
